namespace LealInfoPDV;
// A passive child of the main desktop. It never activates a window or interrupts a sale.
internal sealed class AngraProjectAlert : UserControl
{
 private readonly Panel? reserved;private readonly Form owner;private readonly AngraSyncService service;private readonly Label heading=new(){Text="NOVO PROJETO RECEBIDO",AutoEllipsis=true},count=new(){AutoEllipsis=true,TextAlign=ContentAlignment.TopRight},details=new(){AutoEllipsis=true};
 private readonly SalesVisualButton open=new(){Name="OpenReceivedAngraProject",Text="ABRIR PROJETO"};private readonly System.Windows.Forms.Timer timer=new(){Interval=1000};
 internal AngraProjectAlert(Form owner,AngraSyncService service,bool reserveSpace=false){this.owner=owner;this.service=service;Name="AngraNewProjectAlert";TabStop=false;open.TabStop=false;AutoScaleMode=AutoScaleMode.None;BackColor=Color.FromArgb(12,32,49);ForeColor=Color.White;Font=new Font("Segoe UI",9);heading.ForeColor=Color.FromArgb(0,213,236);count.ForeColor=heading.ForeColor;Controls.AddRange(new Control[]{heading,count,details,open});open.Click+=(_,_)=>OpenFirst();if(reserveSpace){var fill=owner.Controls.Cast<Control>().FirstOrDefault(c=>c.Dock==DockStyle.Fill);reserved=new Panel{Dock=DockStyle.Bottom,Height=126,BackColor=owner.BackColor,Visible=false,TabStop=false};owner.Controls.Add(reserved);if(fill!=null)owner.Controls.SetChildIndex(reserved,owner.Controls.GetChildIndex(fill)+1);}owner.Controls.Add(this);BringToFront();owner.ClientSizeChanged+=LayoutAlert;timer.Tick+=(_,_)=>RefreshNotice();timer.Start();RefreshNotice();}
 private static IEnumerable<Control> Descendants(Control control)=>control.Controls.Cast<Control>().SelectMany(child=>new[]{child}.Concat(Descendants(child)));
 private void LayoutAlert(object? sender,EventArgs e){float scale=owner.DeviceDpi/96f;int S(int n)=>(int)Math.Round(n*scale);if(reserved!=null)reserved.Height=S(126);int width=Math.Max(S(250),Math.Min(S(390),owner.ClientSize.Width-S(24)));int footerTop=Descendants(owner).OfType<StatusStrip>().Where(s=>s.Visible).Select(s=>owner.PointToClient(s.PointToScreen(Point.Empty)).Y).Where(y=>y>owner.ClientSize.Height/2).DefaultIfEmpty(owner.ClientSize.Height-S(24)).Min();SetBounds(Math.Max(S(8),owner.ClientSize.Width-width-S(12)),Math.Max(S(8),footerTop-S(126)),width,S(114));heading.SetBounds(S(12),S(8),width-S(150),S(22));count.SetBounds(width-S(146),S(9),S(134),S(22));details.SetBounds(S(12),S(34),width-S(24),S(38));open.SetBounds(width-S(180),S(75),S(168),S(32));}
 internal void RefreshNotice(){if(IsDisposed||owner.IsDisposed)return;var unread=service.Notifications?.Unread()??Array.Empty<AngraProjectNotice>();if(reserved!=null)reserved.Visible=unread.Count>0;Visible=unread.Count>0;if(unread.Count>0){count.Text=unread.Count+" NÃO VISUALIZADO(S)";details.Text="Cliente: "+unread[0].Customer+"\n"+unread[0].Title;LayoutAlert(this,EventArgs.Empty);BringToFront();Invalidate(true);Update();}}
 internal void OpenFirst(){var item=service.Notifications?.Unread().FirstOrDefault();if(item==null)return;try{var saved=GlassProjectStore.Load(item.LocalId);if(saved.Data.AppProject!=null&&!AngraProjectData.LegacyCompatible(saved.Data)){using var form=new AngraProjectForm(saved);form.ShowDialog(owner);}else{using var form=new GlassWorkshopForm();form.Shown+=(_,_)=>form.LoadSavedProject(item.LocalId);form.ShowDialog(owner);}RefreshNotice();}catch(Exception e){MessageBox.Show(owner,e.Message,"Projeto recebido",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
 protected override void Dispose(bool disposing){if(disposing){timer.Dispose();owner.ClientSizeChanged-=LayoutAlert;reserved?.Dispose();}base.Dispose(disposing);}
}
